/**
 * Writes `fixtures/package/v16/annotations.buildbox`, its `project.json` and its asset (#81 §1).
 *
 * Run it with `npx vite-node scripts/make-v16-package-fixture.ts`. The file is an ordinary production
 * Backup — the format this build writes — so any build can run the generator. Like every golden file
 * it is committed bytes, never regenerated by a test; `fixtures.test.ts` proves these bytes still
 * round-trip.
 *
 * The scene is the v15 one beside it, unchanged, with the one thing the sixteenth schema added drawn
 * on the scene the record already carries: five Annotations — a Text note, a Leader anchored to a
 * Wall face, an Arrow with a free Endpoint owned by a Design Option, a Revision Cloud over the
 * appliance wall, and a Reference Marker on an Elevation View pointing at the Plan View. It is the
 * bytes the round-trip of a Project that holds an Annotation is judged against.
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { canonicalJsonBytes } from '../src/lib'
import { encodeProject } from '../src/package/encode'
import { annotationsFixtureProject, FIXTURE_BUILD, FIXTURE_PLAN_IMAGE_HASH } from '../src/package/testing'

const assetBytes = readFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
const assetSource = async (): Promise<{ bytes: Uint8Array; mediaType: string }> => ({
  bytes: new Uint8Array(assetBytes),
  mediaType: 'image/png',
})

const project = annotationsFixtureProject()
const bytes = await encodeProject(project, assetSource, FIXTURE_BUILD)

const dir = join('fixtures', 'package', 'v16')
mkdirSync(join(dir, 'assets'), { recursive: true })
writeFileSync(join(dir, 'annotations.buildbox'), bytes)
writeFileSync(join(dir, 'project.json'), `${new TextDecoder().decode(canonicalJsonBytes(project))}\n`)
copyFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`), join(dir, 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
console.info(`wrote ${join(dir, 'annotations.buildbox')}: ${String(bytes.length)} bytes`)
